		let arrow1 = [
			Math.cos(dirAngle + arrowAngle) * arrowSize,
			Math.sin(dirAngle + arrowAngle) * arrowSize
		];
		let arrow2 = [
			Math.cos(dirAngle - arrowAngle) * arrowSize,
			Math.sin(dirAngle - arrowAngle) * arrowSize
		];
		this.__ctx.lineTo(pos[0] + dir[0] + arrow1[0], pos[1] + dir[1] + arrow1[1]);
		this.__ctx.moveTo(pos[0] + dir[0], pos[1] + dir[1]);
